import pandas as pd

trips = tables['trips']

# Bin by period and analyze
def get_period(doy):
    if 80 <= doy < 120:
        return 'April (80-120)'
    elif 120 <= doy < 160:
        return 'May-June (120-160)'
    elif 160 <= doy < 210:
        return 'June-July (160-210)'
    elif 210 <= doy < 270:
        return 'Aug-Sept (210-270)'
    elif 270 <= doy < 310:
        return 'October (270-310)'
    else:
        return 'Other'

trips['period'] = trips['fish_date_doy'].apply(get_period)

# Summary by period and class
summary = trips.groupby(['period', 'cls'])['yt'].agg(['count', 'sum', 'mean']).round(2)
summary.columns = ['trips', 'total_yt', 'avg_yt']

# Print it sorted by period and avg
result = summary.reset_index().sort_values(['period', 'avg_yt'], ascending=[True, False])
print(result.to_string())
